	//#region globe.ts
	const RAD = Math.PI / 180;
	function buildDataset(rows, origin) {
		const n = rows.length;
		const lats = new Float64Array(n);
		const lons = new Float64Array(n);
		const px = new Float64Array(n);
		const py = new Float64Array(n);
		const pz = new Float64Array(n);
		for (let i = 0; i < n; i += 1) {
			const lat = rows[i][3];
			const lon = rows[i][4];
			lats[i] = lat;
			lons[i] = lon;
			const phi = lat * RAD;
			const lam = lon * RAD;
			const cphi = Math.cos(phi);
			px[i] = cphi * Math.cos(lam);
			py[i] = cphi * Math.sin(lam);
			pz[i] = Math.sin(phi);
		}
		return {
			origin,
			rows,
			lats,
			lons,
			px,
			py,
			pz
		};
	}
	function parseSeed(text) {
		if (!text || text === "[]") return [];
		try {
			const parsed = JSON.parse(text);
			if (!Array.isArray(parsed)) return [];
			const out = [];
			for (const row of parsed) if (Array.isArray(row) && row.length >= 5 && typeof row[0] === "string" && typeof row[3] === "number") out.push(row);
			return out;
		} catch (_unused) {
			return [];
		}
	}
	function haversine(lat1, lon1, lat2, lon2) {
		const dLat = (lat2 - lat1) * RAD;
		const dLon = (lon2 - lon1) * RAD;
		const a = Math.sin(dLat / 2) * Math.sin(dLat / 2) + Math.cos(lat1 * RAD) * Math.cos(lat2 * RAD) * Math.sin(dLon / 2) * Math.sin(dLon / 2);
		return 12742 * Math.asin(Math.min(1, Math.sqrt(a)));
	}
	function nearestIn(dataset, lat, lon, want) {
		const hits = [];
		const { lats, lons, rows } = dataset;
		const n = rows.length;
		for (let i = 0; i < n; i += 1) {
			const km = haversine(lat, lon, lats[i], lons[i]);
			if (hits.length < want) {
				hits.push({
					row: rows[i],
					km
				});
				if (hits.length === want) hits.sort((a, b) => a.km - b.km);
			} else if (km < hits[hits.length - 1].km) {
				hits[hits.length - 1] = {
					row: rows[i],
					km
				};
				let j = hits.length - 1;
				while (j > 0 && hits[j - 1].km > hits[j].km) {
					const t = hits[j - 1];
					hits[j - 1] = hits[j];
					hits[j] = t;
					j -= 1;
				}
			}
		}
		return hits;
	}
